import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  NewsRepository get _newsRepository => context.read<NewsRepository>();

  /// Кэш ленты: показывается сразу при открытии вкладки.
  List<NewsModel> _cachedNews = const [];

  /// Свежая лента, пришедшая из сети в фоне.
  List<NewsModel>? _freshNews;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  /// cache-then-network: сначала мгновенно показываем кэш, параллельно
  /// запрашиваем сеть и обновляем список, когда придёт ответ.
  void _initData() {
    final NewsRepository newsRepository = _newsRepository;

    newsRepository.loadNewsFeed(NewsFeedFilter.all).then((List<NewsModel> cached) {
      if (!mounted) return;

      setState(() => _cachedNews = cached);
      _scaleController.forward(); // запускаем анимацию
    });

    newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> fresh) {
      if (!mounted) return;

      setState(() => _freshNews = fresh);
      _scaleController.forward(); // запускаем анимацию
    });
  }

  @override
  Widget build(BuildContext context) {
    final List<NewsModel> data = _freshNews ?? _cachedNews;

    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: data.isEmpty
          ? const SizedBox.shrink()
          : ScaleTransition(
              scale: _scaleAnimation,
              child: ListView.builder(
                itemCount: data.length,
                itemBuilder: (BuildContext context, int index) {
                  final NewsModel news = data[index];

                  return Padding(
                    key: ValueKey(news.link),
                    padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                    child: NewsCard(model: news),
                  );
                },
                padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
              ),
            ),
    );
  }
